// --- llmtool.FModel.model.Lt
// Compare two fields. Comparison is anti-symmetric: if a>b, then !(b>a).
inline bool llmtool::model_Lt(llmtool::FModel& parent, llmtool::FModel &rhs) {
    return algo::Smallstr50_Lt(parent.model,rhs.model);
}

